Ltac finite_finish :=
  finite_normalize;
  first [apply finite_id
  | match goal with
    | |- ?P |-- (?Q ** ?R) =>
        eapply (finite_trans _ (Q ** _) _);
        [finite_pick | apply finite_frame; [apply finite_id | finite_finish]]
    end
  | intros ? HU;
    solve [cbv [andp coq_prop]; repeat split; try assumption; reflexivity]].
